import { FC, HTMLAttributes } from 'react';

import { Flex } from 'antd';

import { BrandCard } from 'entities/Brand';
import { BrandsFilters } from 'features/Filters';
import { MOCK_IBrand } from 'shared/consts/MOCK_FOR_CATALOG';
import { NoResults, OverlayLoader } from 'shared/ui';

interface IBrandListProps extends HTMLAttributes<HTMLDivElement> {
	data: MOCK_IBrand[];
	isFetching: boolean;
	isLoading: boolean;
}

export const BrandList: FC<IBrandListProps> = ({ data, isFetching, isLoading, ...props }) => {
	return (
		<Flex {...props} vertical gap={8}>
			{isFetching && <OverlayLoader />}
			<BrandsFilters />
			{!isLoading && !data?.length && <NoResults />}
			<Flex vertical gap={8}>
				{data?.map((brand) => <BrandCard brand={brand} key={brand.id} />)}
			</Flex>
		</Flex>
	);
};
