import { FC } from 'react';
import { Link, type LinkProps } from 'react-router-dom';

import { Flex, Tag, Typography } from 'antd';
import cn from 'classnames';

import OfferIcon from 'assets/images/icons/brand/offer.svg?react';
import { MOCK_IBrand } from 'shared/consts/MOCK_FOR_CATALOG';
import { EMainRoutes } from 'shared/typings';

import { BrandHeader } from '../BrandHeader/BrandHeader';
import { CatalogPostCard } from '../CatalogPostCard/CatalogPostCard';

import styles from './BrandCard.module.scss';

interface IBrandCardProps extends Partial<LinkProps> {
	brand: MOCK_IBrand;
}

export const BrandCard: FC<IBrandCardProps> = ({ className, brand, ...props }) => {
	return (
		<Link {...props} className={cn(className, styles.brandCard)} to={`/${EMainRoutes.BRAND}/${brand.id}`}>
			<BrandHeader brand={brand} isShortView />
			<Flex gap={12} className={styles.brandCard__info}>
				<Typography.Text className={styles.brandCard__average} strong>
					{brand.average}
				</Typography.Text>
				<Tag className={styles.brandCard__tag} icon={<OfferIcon />}>
					{brand.posts.length}
				</Tag>
			</Flex>
			<Flex gap={8} className={styles.brandCard__footer}>
				{brand.posts?.map((post) => <CatalogPostCard key={post.id} post={post} isShortView />)}
			</Flex>
		</Link>
	);
};
