import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, Input, Select, Switch, Typography } from 'antd';

import RecommendedIcon from 'assets/images/icons/recommended.svg?react';
import { EFilters, OPTIONS_MAX_HEIGHT_NOTIFICATIONS, useFilters } from 'features/Filters';

import styles from './BrandsFilters.module.scss';

interface IBrandsFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const BrandsFilters: FC<IBrandsFiltersProps> = ({ ...props }) => {
	const { t } = useTranslation();
	const { getFilterValue, onFilterChange } = useFilters(true);

	const categoryOptions = [{ label: '1', value: '0' }]; //TODO:
	const typeOptions = [{ label: '1', value: '0' }]; //TODO:

	return (
		<Flex {...props} vertical gap={8}>
			<Input.Search
				placeholder={t('Поиск')}
				onSearch={(value) => onFilterChange(EFilters.SEARCH, value)}
				value={getFilterValue(EFilters.SEARCH) || ''}
				allowClear
				size="large"
			/>
			<Select
				value={getFilterValue(EFilters.CATEGORY)}
				options={categoryOptions}
				onChange={(value) => onFilterChange(EFilters.CATEGORY, value)}
				size="large"
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				allowClear
				placeholder={t('Категория бренда')}
			/>
			<Select
				value={getFilterValue(EFilters.TYPE)}
				options={typeOptions}
				onChange={(value) => onFilterChange(EFilters.TYPE, value)}
				size="large"
				listHeight={OPTIONS_MAX_HEIGHT_NOTIFICATIONS}
				allowClear
				placeholder={t('Тип офера')}
			/>
			<Flex gap={8} align={'center'} className={styles.brandsFilters__recomended}>
				<RecommendedIcon className={styles.brandHeader__img} />
				<Typography.Text className={styles.brandsFilters__w100}>{t('Рекомендации ИИ')}</Typography.Text>
				<Switch
					value={!!getFilterValue(EFilters.AI_RECOMENDATION)}
					onChange={(value) => onFilterChange(EFilters.AI_RECOMENDATION, value)}
				/>
			</Flex>
		</Flex>
	);
};
